public class Rec {

    static long sum(int[] a, int i) {
        if (i == a.length) {
            return 0;
        }
        return a[i] + sum(a, i + 1);
    }

    static int countEven(int[] a, int i) {
        if (i == a.length) {
            return 0;
        }
        return (a[i] % 2 == 0 ? 1 : 0) + countEven(a, i + 1);
    }

    static int max(int[] a, int i) {
        if (i == a.length - 1) {
            return a[i];
        }
        return Math.max(a[i], max(a, i + 1));
    }
}

